assert 'next_SMA_rebinding_contract' not in before
contract={'current_original_state':rel(R/'forward_state.json'),'current_original_report':rel(R/'forward_report.json'),'next_window_utc':h['next_SMA_single_window_utc'],'mode':'original_daily_decision_requires_new_full78_before_reserve','expected_original_daily_events_utc':h['next_window_original_daily_events']['SMA'],'full77_authority':bg['authority'],'full77_sha256':bg['sha256'],'old_full76_prefix_authority':bg['full76_authority'],'old_full76_sha256':bg['full76_sha256'],'required_full_daily_context':78,'full78_currently_captured':False,'required_template_sources':{k:h[k] for k in ['SMA_next_original_daily_adapter_template','SMA_next_original_daily_registry_template','SMA_next_original_daily_audit_template']},'all_templates_and_previous_state_require_rebinding_before_any_next_reservation':True,'preserve_original_Float_arithmetic_and_SPOT_costs':True,'next_reserve_requires_new_real_full78_exact77prefix_and_ownminute_overlap':True}
